#!/bin/sh
# Envuelve la página del armador en un documento HTML completo para GitHub Pages.
cd "$(dirname "$0")"
{ printf '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta property="og:type" content="website"><meta property="og:site_name" content="Fútbol PAS"><meta property="og:title" content="Fútbol PAS"><meta property="og:description" content="Votá a cada jugador y armá equipos parejos."><meta property="og:url" content="https://futbolpas.pages.dev/"><meta property="og:image" content="https://futbolpas.pages.dev/og.jpg?v=2"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><meta name="description" content="Votá a cada jugador y armá equipos parejos."><style>:root{padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}[hidden]{display:none!important}img{max-width:100%%}</style></head><body>\n'; cat ../nuevo-partido.html; printf '\n</body></html>\n'; } > index.html
